// Verify the HMAC signature that Convex puts on every webhook call.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const ts = headers['x-lendloop-timestamp'];
const sig = headers['x-lendloop-signature'];
const secret = $env.LENDLOOP_WEBHOOK_SECRET;

// Raw body is kept as binary so the signature is checked on the exact bytes that were sent.
const rawBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const raw = rawBuffer.toString('utf8');

let valid = false;
if (secret && ts && sig && Math.abs(Date.now() / 1000 - Number(ts)) <= 300) {
  const path = '/webhook/lendloop-loan-event';
  const expected = crypto.createHmac('sha256', secret).update(ts + '.POST.' + path + '.' + raw).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(String(sig));
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
}
return [{ json: { valid, payload: valid ? JSON.parse(raw) : null } }];

// Mock notification: logs the message. Swap for an Email/Slack/Discord node in production.
const p = $input.first().json.payload;
const subject = {
  request_created: 'New borrow request for your ' + p.toolName,
  approved: 'Your request for ' + p.toolName + ' was approved',
  declined: 'Your request for ' + p.toolName + ' was declined',
  returned: p.toolName + ' was marked as returned',
}[p.event] || ('Update on ' + p.toolName);
const message = 'To: ' + p.recipientEmail + '\nSubject: ' + subject + '\nDates: ' + p.startDate + ' to ' + p.endDate;
console.log('[LendLoop notification]\n' + message);
return [{ json: { sent: true, message } }];
